# boxctl: timeout=120
W=~/work/sidnet; tail -6 $W/logs/timeline.log | cut -c1-700; for f in buildB freshB freshB_val; do [ -f $W/logs/$f.log ] && echo "$f: $(tail -1 $W/logs/$f.log | cut -c1-300)"; done; [ -f $W/logs/s0.err ] && echo "s0.err: $(tail -2 $W/logs/s0.err | cut -c1-250)"; [ -f $W/logs/s0.out ] && echo "s0.out lines: $(wc -l < $W/logs/s0.out)"; ls $W/shards 2>/dev/null | grep -c npz$ | sed "s/^/shard files: /"; ls -la $W/data/*.npz 2>/dev/null | awk "{print \$5, \$9}"; echo "units: $(systemctl is-active sidnet-run2)"; uptime | sed "s/.*load/load/"; free -g | sed -n 2p | cut -c1-80; df -h $HOME | tail -1
